INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Datensicherheit dasselbe wie Datenschutz?', 2, '[{"text": "Nein", "correct": true, "because": "Sicherheit schützt Systeme, Datenschutz Personen"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Schwerpunkte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Datensicherheit?', 3, '[{"text": "Daten vor unbefugtem Zugriff schützen", "correct": true, "because": "Sicherheit gewährleisten"}, {"text": "Hardware optimieren", "correct": false, "because": "Kein Hardware-Fokus"}, {"text": "Software entwickeln", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen gehören zur Datensicherheit?', 5, '[{"text": "Firewall", "correct": true, "because": "Blockiert Angriffe"}, {"text": "Verschlüsselung", "correct": true, "because": "Schützt Daten"}, {"text": "Grafikdesign", "correct": false, "because": "Kein Sicherheitsmittel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datensicherheit schützt vor Datenverlust. b) Sie ist nur für Unternehmen relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch privat wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Datensicherheit?', 4, '[{"text": "Bedrohungsanalyse", "correct": false, "because": "Risiken erkennen"}, {"text": "Backup-Strategie", "correct": false, "because": "Daten wiederherstellen"}, {"text": "Bildschirmfarbe", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Datensicherheit nur digitale Daten betrifft?', 2, '[{"text": "Nein", "correct": true, "because": "Auch physische Daten"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft bei der Datensicherheit?', 3, '[{"text": "Antivirus-Software", "correct": true, "because": "Erkennt Bedrohungen"}, {"text": "Texteditor", "correct": false, "because": "Ungeeignet"}, {"text": "Grafiksoftware", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bedrohungen mindert Datensicherheit?', 5, '[{"text": "Malware", "correct": true, "because": "Schädliche Software"}, {"text": "Phishing", "correct": true, "because": "Täuschungsangriffe"}, {"text": "Bildschirmflimmern", "correct": false, "because": "Kein Sicherheitsrisiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Datensicherheit verhindert Datenverlust. b) Sie ist immer kostenlos. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Datensicherheit?', 4, '[{"text": "Verschlüsselung", "correct": false, "because": "Schützt Daten"}, {"text": "Zugriffskontrolle", "correct": false, "because": "Beschränkt Zugriff"}, {"text": "Küchenzeile", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Datensicherheit nur für Datenbanken?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Dateien, Systeme"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken fördern Datensicherheit?', 4, '[{"text": "Backups", "correct": true, "because": "Wiederherstellung möglich"}, {"text": "Intrusion Detection", "correct": true, "because": "Erkennt Angriffe"}, {"text": "Monitorauflösung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Datensicherheit unnötig ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Schutz vor Bedrohungen"}, {"text": "Ja", "correct": false, "because": "Risiken vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Datensicherheit?', 3, '[{"text": "Bedrohungsprävention", "correct": true, "because": "Schutz vor Angriffen"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Sorgfalt wichtiger"}, {"text": "Minimale Kosten", "correct": false, "because": "Sicherheit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datensicherheit schützt vor Cyberangriffen. b) Sie ist nur für digitale Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch physische Daten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei der Datensicherheit?', 5, '[{"text": "Cyberangriffe", "correct": true, "because": "Ständige Bedrohung"}, {"text": "Menschliche Fehler", "correct": true, "because": "Schwachstelle"}, {"text": "Bildschirmgröße", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Datensicherheit unwichtig?', 3, '[{"text": "Patch-Management", "correct": false, "because": "Lücken schließen"}, {"text": "Überwachung", "correct": false, "because": "Bedrohungen erkennen"}, {"text": "Tastaturtyp", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Datensicherheit komplett garantieren?', 3, '[{"text": "Nein", "correct": true, "because": "Risiken bleiben"}, {"text": "Ja", "correct": false, "because": "Keine absolute Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Datensicherheit nur für Firmen ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch privat relevant"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Verschlüsselung?', 4, '[{"text": "Schützt Daten", "correct": true, "because": "Unlesbar für Unbefugte"}, {"text": "Erhöht Bandbreite", "correct": false, "because": "Kein Netzwerkeffekt"}, {"text": "Verbessert Grafik", "correct": false, "because": "Irrelevant"}]');
